SELECT p.gender, CASE WHEN p.age BETWEEN 42 AND 52 THEN l.valueuom END AS age_group, CASE WHEN l.value < 0.014 THEN 'Normal' WHEN l.value BETWEEN 0.014 AND 0.04 THEN 'Borderline' ELSE 'Myocardial Injury' END AS troponin_category, COUNT(DISTINCT p.subject_id) AS patient_count FROM patients p JOIN labevents l ON p.subject_id = l.subject_id WHERE p.gender = 'F' AND l.itemid = 718777 AND l.valueuom = 'ng/mL' GROUP BY p.gender, age_group, troponin_category ORDER BY p.gender, age_group, troponin_category NULLS LAST;